@push('page-styles')
<style>
    .auth-page{min-height:78vh;display:grid;place-items:center;padding:150px 20px 80px;background:#f6f7f9;color:#172033}.auth-card{width:min(520px,100%);padding:34px;border:1px solid #e2e8f0;border-radius:20px;background:#fff;box-shadow:0 24px 70px rgba(15,23,42,.08)}.auth-card>span{color:#0f766e;font-size:10px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.auth-card h1{margin:8px 0 7px;font-size:36px;line-height:1.1}.auth-card>p{margin:0 0 25px;color:#64748b;line-height:1.7}.auth-status{margin-bottom:16px;padding:11px 13px;border-radius:9px;background:#ecfdf5;color:#047857;font-size:13px}.auth-field{margin-bottom:16px}.auth-field label{display:block;margin-bottom:6px;color:#334155;font-size:12px;font-weight:850}.auth-field input[type=text],.auth-field input[type=email],.auth-field input[type=password]{width:100%;box-sizing:border-box;padding:12px 13px;border:1px solid #cbd5e1;border-radius:9px;background:#fff;color:#172033;font:inherit;outline:none}.auth-field input:focus{border-color:#0f766e;box-shadow:0 0 0 3px rgba(15,118,110,.12)}.auth-error{margin:6px 0 0;color:#be123c;font-size:12px}.auth-check{display:flex;align-items:center;gap:8px;color:#64748b;font-size:13px}.auth-row{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:23px}.auth-row a{color:#0f766e;font-size:13px;font-weight:800}.auth-submit{padding:12px 18px;border:0;border-radius:9px;background:#172033;color:#fff;font:inherit;font-size:13px;font-weight:850;cursor:pointer}.auth-switch{margin:21px 0 0!important;padding-top:19px;border-top:1px solid #edf0f5;text-align:center}.auth-switch a{color:#0f766e;font-weight:850}@media(max-width:550px){.auth-page{padding:115px 14px 55px}.auth-card{padding:24px}.auth-row{align-items:stretch;flex-direction:column}.auth-submit{width:100%}}
</style>
@endpush
